-- Baseline internal.food_resolve_menu_options(jsonb,jsonb) MD5 8946685445a1c0f1dfcd8057554baacc
CREATE OR REPLACE FUNCTION internal.food_resolve_menu_options(p_groups jsonb, p_selected jsonb)
 RETURNS TABLE(options jsonb, surcharge numeric)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_groups jsonb := case when jsonb_typeof(p_groups) = 'array' then p_groups else '[]'::jsonb end;
  v_selected jsonb;
  v_pick jsonb;
  v_group jsonb;
  v_keys text[] := '{}';
  v_key text;
  v_count integer;
  v_max integer;
  v_options jsonb := '[]'::jsonb;
  v_surcharge numeric := 0;
  v_choice jsonb;
  v_price numeric;
begin
  if p_selected is null or jsonb_typeof(p_selected) = 'null' then
    v_selected := '[]'::jsonb;
  elsif jsonb_typeof(p_selected) <> 'array' or jsonb_array_length(p_selected) > 100 then
    raise exception 'invalid menu option';
  else
    v_selected := p_selected;
  end if;

  -- Every pick must name a real choice of a real group, once.
  for v_pick in select value from jsonb_array_elements(v_selected)
  loop
    if jsonb_typeof(v_pick) <> 'object'
       or coalesce(v_pick->>'group_id', '') = ''
       or coalesce(v_pick->>'choice_id', '') = '' then
      raise exception 'invalid menu option';
    end if;
    v_key := (v_pick->>'group_id') || chr(31) || (v_pick->>'choice_id');
    if v_key = any(v_keys) then
      raise exception 'invalid menu option';
    end if;
    v_keys := v_keys || v_key;
    if not exists (
      select 1
      from jsonb_array_elements(v_groups) g
      cross join lateral jsonb_array_elements(
        case when jsonb_typeof(g.value->'choices') = 'array' then g.value->'choices' else '[]'::jsonb end
      ) c
      where g.value->>'id' = v_pick->>'group_id'
        and c.value->>'id' = v_pick->>'choice_id'
    ) then
      raise exception 'invalid menu option';
    end if;
  end loop;

  -- Group rules, then build the stored selection in menu order.
  for v_group in select value from jsonb_array_elements(v_groups)
  loop
    select count(*) into v_count
    from jsonb_array_elements(v_selected) s
    where s.value->>'group_id' = v_group->>'id';

    v_max := greatest(1, least(20, coalesce(
      case when v_group->>'max_select' ~ '^\s*[0-9]{1,4}(\.[0-9]+)?\s*$' then floor((v_group->>'max_select')::numeric)::integer end,
      1)));
    if v_count > v_max then
      raise exception 'too many menu options selected';
    end if;
    if v_group->'required' = 'true'::jsonb and v_count = 0 then
      raise exception 'required menu option missing';
    end if;

    if v_count > 0 then
      for v_choice in
        select c.value
        from jsonb_array_elements(
          case when jsonb_typeof(v_group->'choices') = 'array' then v_group->'choices' else '[]'::jsonb end
        ) c
        where exists (
          select 1 from jsonb_array_elements(v_selected) s
          where s.value->>'group_id' = v_group->>'id'
            and s.value->>'choice_id' = c.value->>'id'
        )
      loop
        v_price := greatest(0, coalesce(
          case when v_choice->>'price' ~ '^\s*[0-9]{1,7}(\.[0-9]+)?\s*$' then (v_choice->>'price')::numeric end,
          0));
        v_surcharge := v_surcharge + v_price;
        v_options := v_options || jsonb_build_array(jsonb_build_object(
          'group_id', v_group->>'id',
          'group_name', v_group->>'name',
          'choice_id', v_choice->>'id',
          'choice_name', v_choice->>'name',
          'price', v_price
        ));
      end loop;
    end if;
  end loop;

  return query select v_options, round(v_surcharge, 2);
end;
$function$
;

-- Baseline internal.food_schedule_day_key(integer) MD5 fe7c7454b5ebc7dfb7555b2a720993d0
CREATE OR REPLACE FUNCTION internal.food_schedule_day_key(p_isodow integer)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select (array['mon','tue','wed','thu','fri','sat','sun'])[greatest(1, least(7, p_isodow))];
$function$
;

-- Baseline internal.food_set_scheduled_order(uuid,timestamp with time zone) MD5 fb7dd97ba95ac6b2881f9326e03c7d1c
CREATE OR REPLACE FUNCTION internal.food_set_scheduled_order(p_order_id uuid, p_scheduled_for timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_store public.food_stores%rowtype;
  v_order public.food_orders%rowtype;
  v_min timestamptz;
  v_max timestamptz;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if p_scheduled_for is null then raise exception 'scheduled time is required'; end if;

  select * into v_order
  from public.food_orders
  where id = p_order_id and buyer_id = auth.uid()
  for update;
  if not found then raise exception 'order not found'; end if;

  select * into v_store from public.food_stores where id = v_order.store_id;
  if not found then raise exception 'store not found'; end if;
  if not v_store.scheduled_orders_enabled then raise exception 'scheduled orders are not enabled'; end if;

  v_min := now() + make_interval(mins => v_store.scheduled_min_notice_minutes);
  v_max := now() + make_interval(days => v_store.scheduled_max_days);
  if p_scheduled_for < v_min then raise exception 'scheduled time is too soon'; end if;
  if p_scheduled_for > v_max then raise exception 'scheduled time is too far'; end if;
  if not internal.food_store_effectively_open(v_order.store_id, p_scheduled_for) then
    raise exception 'store is closed at scheduled time';
  end if;

  update public.food_orders
  set scheduled_for = p_scheduled_for
  where id = v_order.id;

  insert into public.food_order_events(order_id,event_type,note,actor_id)
  values (
    v_order.id,
    'scheduled',
    left('นัดรับ/จัดส่ง ' || to_char(p_scheduled_for at time zone 'Asia/Bangkok','YYYY-MM-DD HH24:MI'),1000),
    auth.uid()
  );
end;
$function$
;

-- Baseline internal.food_slot_open(jsonb,time without time zone) MD5 1dcd917013ea3f0e79406490d4a2a532
CREATE OR REPLACE FUNCTION internal.food_slot_open(p_slot jsonb, p_local_time time without time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_open time;
  v_close time;
begin
  if p_slot is null or coalesce((p_slot->>'enabled')::boolean, false) = false then
    return false;
  end if;
  begin
    v_open := (p_slot->>'open')::time;
    v_close := (p_slot->>'close')::time;
  exception when others then
    return false;
  end;
  if v_open = v_close then
    return true;
  end if;
  if v_close > v_open then
    return p_local_time >= v_open and p_local_time < v_close;
  end if;
  return p_local_time >= v_open;
end;
$function$
;

-- Baseline internal.food_store_effectively_open(uuid,timestamp with time zone) MD5 ae5f89f16a48fad49bcd20a0c8e54674
CREATE OR REPLACE FUNCTION internal.food_store_effectively_open(p_store_id uuid, p_at timestamp with time zone DEFAULT now())
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_store public.food_stores%rowtype;
  v_local timestamp;
  v_date date;
  v_time time;
  v_dow integer;
  v_today jsonb;
  v_prev jsonb;
  v_prev_open time;
  v_prev_close time;
begin
  select * into v_store from public.food_stores where id = p_store_id;
  if not found or not v_store.is_open or v_store.admin_suspended_at is not null then
    return false;
  end if;

  if v_store.temporary_closed_until is not null and v_store.temporary_closed_until > p_at then
    return false;
  end if;

  v_local := p_at at time zone 'Asia/Bangkok';
  v_date := v_local::date;
  v_time := v_local::time;
  v_dow := extract(isodow from v_local)::integer;

  if v_date = any(coalesce(v_store.special_closed_dates, '{}'::date[])) then
    return false;
  end if;

  -- Legacy fallback: a store with no structured weekly schedule keeps using
  -- the manual is_open flag exactly as before.
  if v_store.business_schedule = '{}'::jsonb
     or jsonb_typeof(v_store.business_schedule->'weekly') <> 'object' then
    return true;
  end if;

  v_today := v_store.business_schedule->'weekly'->internal.food_schedule_day_key(v_dow);
  if internal.food_slot_open(v_today, v_time) then
    return true;
  end if;

  -- Previous-day overnight slot, e.g. 18:00–02:00.
  v_prev := v_store.business_schedule->'weekly'->internal.food_schedule_day_key(case when v_dow = 1 then 7 else v_dow - 1 end);
  if v_prev is not null and coalesce((v_prev->>'enabled')::boolean, false) then
    begin
      v_prev_open := (v_prev->>'open')::time;
      v_prev_close := (v_prev->>'close')::time;
      if v_prev_close < v_prev_open and v_time < v_prev_close then
        return true;
      end if;
    exception when others then
      null;
    end;
  end if;

  return false;
end;
$function$
;

-- Baseline merchant_has_store_role(uuid,text[]) MD5 0bcbf5f020cf1b72ce82d31f86861480
CREATE OR REPLACE FUNCTION public.merchant_has_store_role(p_store_id uuid, p_roles text[] DEFAULT NULL::text[])
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select (select auth.uid()) is not null
    and (
      exists (
        select 1
        from public.food_stores s
        join public.merchant_memberships mm
          on mm.merchant_account_id = s.merchant_account_id
        where s.id = p_store_id
          and mm.user_id = (select auth.uid())
          and mm.active
          and (p_roles is null or mm.role = any(p_roles))
      )
      or exists (
        select 1
        from public.food_staff fs
        where fs.store_id = p_store_id
          and fs.user_id = (select auth.uid())
          and fs.active
          and (
            p_roles is null
            or (case fs.role when 'owner' then 'owner' when 'staff' then 'orders' when 'delivery' then 'delivery' end) = any(p_roles)
          )
      )
    );
$function$
;

-- Baseline merchant_sales_report(uuid) MD5 1d013ec8bc28ff70cca388eea65b90df
CREATE OR REPLACE FUNCTION public.merchant_sales_report(p_store_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_today date := (now() at time zone 'Asia/Bangkok')::date;
  v_week_start date := date_trunc('week', now() at time zone 'Asia/Bangkok')::date;
  v_month_start date := date_trunc('month', now() at time zone 'Asia/Bangkok')::date;
  v_result jsonb;
begin
  if not public.food_has_merchant_access(p_store_id) then
    raise exception 'merchant access required';
  end if;

  with delivered as (
    select
      o.id,
      coalesce(o.total, 0)::numeric as total,
      (o.created_at at time zone 'Asia/Bangkok')::date as order_day
    from public.food_orders o
    where o.store_id = p_store_id
      and o.status = 'delivered'
  ),
  item_totals as (
    select i.item_name as name, sum(i.quantity)::bigint as quantity
    from delivered d
    join public.food_order_items i on i.order_id = d.id
    group by i.item_name
    order by quantity desc, i.item_name asc
    limit 5
  )
  select jsonb_build_object(
    'today_sales', coalesce((select sum(total) from delivered where order_day = v_today), 0),
    'today_orders', (select count(*) from delivered where order_day = v_today),
    'week_sales', coalesce((select sum(total) from delivered where order_day between v_week_start and v_today), 0),
    'week_orders', (select count(*) from delivered where order_day between v_week_start and v_today),
    'month_sales', coalesce((select sum(total) from delivered where order_day between v_month_start and v_today), 0),
    'month_orders', (select count(*) from delivered where order_day between v_month_start and v_today),
    'total_orders', (select count(*) from delivered),
    'average_order', coalesce((select avg(total) from delivered), 0),
    'best', coalesce(
      (select jsonb_agg(jsonb_build_object('name', name, 'quantity', quantity) order by quantity desc, name asc)
       from item_totals),
      '[]'::jsonb
    )
  ) into v_result;

  return v_result;
end;
$function$
;

-- Baseline merchant_set_refund_status(uuid,text,text) MD5 63779727be610d1e2d52d9ad0911e3b5
CREATE OR REPLACE FUNCTION public.merchant_set_refund_status(p_order_id uuid, p_status text, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_order public.food_orders%rowtype;
  v_note text := nullif(left(trim(coalesce(p_note,'')),800),'');
begin
  select * into v_order
  from public.food_orders
  where id=p_order_id
  for update;

  if not found then raise exception 'order not found'; end if;
  if not public.merchant_has_store_role(v_order.store_id, array['owner','admin','manager','orders']) then
    raise exception 'order management role required';
  end if;
  if v_order.payment_provider = 'stripe' then
    raise exception 'stripe refunds must be processed through the payment gateway';
  end if;
  if v_order.status <> 'cancelled' then
    raise exception 'refund is available after cancellation';
  end if;
  if p_status not in ('pending','refunded','failed') then
    raise exception 'invalid refund status';
  end if;
  if v_order.payment_status not in ('paid','refunded') then
    raise exception 'order is not eligible for refund';
  end if;

  update public.food_orders
  set refund_status=p_status,
      refund_note=v_note,
      refund_requested_at=case
        when p_status='pending' then coalesce(refund_requested_at,now())
        else refund_requested_at
      end,
      refunded_at=case when p_status='refunded' then now() else refunded_at end,
      refund_updated_by=(select auth.uid()),
      payment_status=case when p_status='refunded' then 'refunded' else payment_status end
  where id=p_order_id;

  insert into public.food_order_events(order_id,event_type,note,actor_id)
  values (p_order_id,'refund_' || p_status,v_note,(select auth.uid()));

  if p_status='refunded' and v_order.buyer_id is not null then
    insert into public.notifications(recipient_id,actor_id,type,reason)
    values (
      v_order.buyer_id,null,'system',
      'คืนเงินออเดอร์ #' || v_order.order_number || ' แล้ว'
    );
  end if;
end;
$function$
;
CREATE TRIGGER food_orders_block_suspended_store BEFORE INSERT ON public.food_orders FOR EACH ROW EXECUTE FUNCTION internal.food_order_block_suspended_store();
CREATE TRIGGER food_orders_gp_snapshot BEFORE INSERT OR UPDATE OF gp_rate_bp, gp_rate_id, gp_rule_version ON public.food_orders FOR EACH ROW EXECUTE FUNCTION internal.food_orders_gp_snapshot();
CREATE TRIGGER food_orders_guard_store_schedule BEFORE INSERT ON public.food_orders FOR EACH ROW EXECUTE FUNCTION internal.food_order_guard_store_schedule();
CREATE TRIGGER food_orders_notify_merchant_payment AFTER INSERT OR UPDATE OF payment_status ON public.food_orders FOR EACH ROW EXECUTE FUNCTION internal.food_order_notify();
CREATE TRIGGER food_orders_status_notify AFTER UPDATE OF status ON public.food_orders FOR EACH ROW EXECUTE FUNCTION internal.food_order_status_notify();
CREATE TRIGGER food_orders_touch_updated_at BEFORE UPDATE ON public.food_orders FOR EACH ROW EXECUTE FUNCTION food_touch_updated_at();
CREATE TRIGGER trg_food_guard_late_slip BEFORE UPDATE OF payment_status ON public.food_orders FOR EACH ROW EXECUTE FUNCTION internal.food_guard_late_slip();
CREATE TRIGGER trg_food_orders_wynos_food_only BEFORE INSERT ON public.food_orders FOR EACH ROW EXECUTE FUNCTION internal.food_order_wynos_food_only_guard();

alter table public.food_orders enable row level security;
create policy synthetic_order_read on public.food_orders for select to authenticated using(buyer_id=auth.uid() or public.food_has_merchant_access(store_id));
-- Deliberately permissive pre-existing UPDATE policies exercise new restrictive guards.
create policy synthetic_order_update on public.food_orders for update to authenticated using(true) with check(true);
alter table public.food_stores enable row level security;
create policy synthetic_store_read on public.food_stores for select to authenticated using(true);
create policy synthetic_store_update on public.food_stores for update to authenticated using(public.merchant_has_store_role(id,array['owner','admin'])) with check(public.merchant_has_store_role(id,array['owner','admin']));
grant usage on schema public,auth,internal,storage to anon,authenticated,service_role;
grant select,insert,update,delete on all tables in schema public,storage to authenticated,service_role;
grant usage,select on all sequences in schema public to authenticated,service_role;
CREATE OR REPLACE FUNCTION public.food_submit_store_review(p_order_id uuid, p_rating integer, p_review_text text DEFAULT NULL::text, p_tags text[] DEFAULT '{}'::text[], p_anonymous boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_order public.food_orders%rowtype;
  v_review_id uuid;
  v_text text := nullif(left(btrim(coalesce(p_review_text,'')),500),'');
  v_tags text[];
  v_label text;
begin
  if (select auth.uid()) is null or not public.food_customer_access_enabled() then
    raise exception 'food customer access required';
  end if;
  if p_rating is null or p_rating < 1 or p_rating > 5 then
    raise exception 'invalid review rating';
  end if;

  select array(
    select distinct btrim(t)
    from unnest(coalesce(p_tags,'{}'::text[])) as t
    where btrim(t) <> ''
    order by btrim(t)
  ) into v_tags;

  if cardinality(v_tags) > 5
     or not (v_tags <@ array['อร่อย','ปริมาณดี','แพ็กดี','ตรงปก','คุ้มราคา','ส่งเร็ว']::text[]) then
    raise exception 'invalid review tags';
  end if;

  select * into v_order
  from public.food_orders
  where id = p_order_id
    and buyer_id = (select auth.uid())
  for share;

  if not found then
    raise exception 'order not found';
  end if;
  if v_order.status <> 'delivered' or v_order.delivered_at is null then
    raise exception 'only delivered orders can be reviewed';
  end if;
  if exists (select 1 from public.food_store_reviews r where r.order_id = p_order_id) then
    raise exception 'order already reviewed';
  end if;

  v_label := case
    when coalesce(p_anonymous,false) then 'ไม่ระบุชื่อ'
    else internal.food_mask_reviewer_name(v_order.recipient_name)
  end;

  insert into public.food_store_reviews(
    order_id, store_id, buyer_id, rating, review_text, tags,
    reviewer_label, is_anonymous
  ) values (
    v_order.id, v_order.store_id, v_order.buyer_id, p_rating, v_text, v_tags,
    v_label, coalesce(p_anonymous,false)
  )
  returning id into v_review_id;

  return v_review_id;
end;
$function$
;

create function internal.food_mask_reviewer_name(text) returns text language sql immutable as $$select left($1,1)||'***'$$;
create table public.qa_admin_permissions(user_id uuid,section text,action text);
create function internal.has_admin_permission(text,text) returns boolean language sql stable as $$select exists(select 1 from public.qa_admin_permissions where user_id=auth.uid() and section=$1 and action=$2)$$;
set check_function_bodies=on;
